package bd.trend99.app;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.core.app.ActivityScenario;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import static androidx.test.espresso.Espresso.*;import static androidx.test.espresso.action.ViewActions.*;import static androidx.test.espresso.assertion.ViewAssertions.*;import static androidx.test.espresso.matcher.ViewMatchers.*;import static org.hamcrest.Matchers.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class JourneyTest {
 ActivityScenario<MainActivity> scenario;volatile boolean rejectLogin=false,rejectStock=false;volatile JSONObject order;
 @Before public void start(){MainActivity.testTransport=(path,payload,token)->{if(path.contains("/products?"))return "[{\"id\":\"p1\",\"business_id\":\"b1\",\"name_en\":\"Test product\",\"name_bn\":\"Test\",\"price_paisa\":12500,\"stock\":2}]";if(path.contains("/token?")){if(rejectLogin)throw new Exception("Invalid login credentials");return "{\"access_token\":\"test-token\",\"user\":{\"id\":\"u1\"}}";}if(path.contains("/delivery_rates?"))return "[{\"district\":\"Dhaka\",\"delivery_paisa\":6000},{\"district\":\"Chattogram\",\"delivery_paisa\":12000}]";if(path.contains("place_cod_order")){order=new JSONObject(payload.toString());if(rejectStock)throw new Exception("Insufficient stock");return "\"test-order\"";}throw new Exception("Unexpected request: "+path);};scenario=ActivityScenario.launch(MainActivity.class);waitNetwork();}
 void waitNetwork()throws Exception{long end=System.currentTimeMillis()+10000;while(System.currentTimeMillis()<end){final boolean[] done={false};scenario.onActivity(a->done[0]=!a.busy);if(done[0]){Thread.sleep(150);return;}Thread.sleep(50);}fail("Network timeout");}
 void login()throws Exception{onView(withText("Account")).perform(click());onView(withHint("Email")).perform(typeText("test@example.invalid"),closeSoftKeyboard());onView(withHint("Password")).perform(typeText("test-password"),closeSoftKeyboard());onView(withText("Sign in")).perform(click());waitNetwork();}
 void cart()throws Exception{login();onView(withText("Shop")).perform(click());waitNetwork();onView(withText("Add: Test product")).perform(click());onView(withText("Cart")).perform(click());waitNetwork();}
 void submit()throws Exception{onView(withHint("Full name")).perform(scrollTo(),typeText("Test Customer"),closeSoftKeyboard());onView(withHint("Mobile")).perform(scrollTo(),typeText("01700000000"),closeSoftKeyboard());onView(withHint("Area")).perform(scrollTo(),typeText("Test Area"),closeSoftKeyboard());onView(withHint("Address")).perform(scrollTo(),typeText("Test address only"),closeSoftKeyboard());onView(withText("Place COD order")).perform(scrollTo(),click());waitNetwork();}
 @Test public void validLogin()throws Exception{login();onView(withText("Signed in")).check(matches(isDisplayed()));}
 @Test public void invalidLogin()throws Exception{rejectLogin=true;login();onView(withText("Invalid login credentials")).check(matches(isDisplayed()));}
 @Test public void districtAndCheckout()throws Exception{cart();onView(withText("Estimated total: BDT 185.00")).check(matches(isDisplayed()));onView(isAssignableFrom(android.widget.Spinner.class)).perform(click());onData(allOf(is(instanceOf(String.class)),is("Chattogram"))).perform(click());onView(withText("Estimated total: BDT 245.00")).check(matches(isDisplayed()));submit();onView(withText(containsString("COD order received"))).check(matches(isDisplayed()));assertEquals("Chattogram",order.getString("p_district"));assertEquals(1,order.getJSONArray("p_items").getJSONObject(0).getInt("quantity"));assertFalse(order.has("subtotal_paisa"));}
 @Test public void stockChangedAndRetry()throws Exception{cart();rejectStock=true;submit();onView(withText("Insufficient stock")).check(matches(isDisplayed()));String first=order.getString("p_key");rejectStock=false;onView(withText("Place COD order")).perform(scrollTo(),click());waitNetwork();assertEquals(first,order.getString("p_key"));onView(withText(containsString("COD order received"))).check(matches(isDisplayed()));}
 @After public void stop(){if(scenario!=null)scenario.close();MainActivity.testTransport=null;}
}
